 @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("state",MODE_PRIVATE);engine=new FileEngine(this);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->back());dark=prefs.getBoolean("dark",false);gridMode=prefs.getBoolean("grid",false);hidden=prefs.getBoolean("hidden",false);build();restore();if(prefs.getBoolean("pending",false)&&!busy){alert("Operação interrompida","A operação anterior não foi confirmada. Confira a origem e o destino antes de tentar novamente. Não repetimos nem removemos arquivos automaticamente.");prefs.edit().putBoolean("pending",false).apply();}}
