 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(fg);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 GradientDrawable bevel(boolean inset){GradientDrawable d=new GradientDrawable();d.setColor(inset?panel:bg);d.setStroke(dp(1),dark?0xff777777:0xff666666);d.setCornerRadius(0);return d;}
